wp:postmeta.wp:meta_value:
a:7:{s:8:"metadata";a:5:{s:4:"type";s:8:"template";s:9:"shortcode";s:38:"s-60c52bc9-4eff-45fb-a648-ed6d49c13f0c";s:9:"isPrimary";s:0:"";s:5:"title";s:3:"FAQ";s:23:"reviewLocationShortcode";s:24:"[rank_math_rich_snippet]";}s:5:"@type";s:7:"FAQPage";s:4:"name";s:74:"سوالات متداول فیزیوتراپی بعد از جراحی فک";s:3:"url";s:5:"%url%";s:13:"datePublished";s:20:"%date(Y-m-dTH:i:sP)%";s:12:"dateModified";s:24:"%modified(Y-m-dTH:i:sP)%";s:10:"mainEntity";a:4:{i:0;a:4:{s:5:"@type";s:8:"Question";s:4:"name";s:96:"فیزیوتراپی بعد از جراحی فک از چه زمانی باید شروع شود؟";s:3:"url";s:207:"https://dralirezasadighi.com/%d9%db%8c%d8%b2%db%8c%d9%d8%aa%d8%b1%d8%a7%d9%be%db%8c-%d8%a8%d8%b9%d8%af-%d8%a7%d8%b2-%d8%ac%d8%b1%d8%a7%d8%ad%db%8c-%d9%da%a9-%d8%b1%d8%a7%d9%d9%d9%d8%a7%db%8c-%da%a9%d8%a7%d9/";s:14:"acceptedAnswer";a:2:{s:5:"@type";s:6:"Answer";s:4:"text";s:696:"زمان شروع فیزیوتراپی بعد از جراحی فک برای همه یکسان نیست و به نوع جراحی، وضعیت استخوان‌ها، مفصل فک و روند ترمیم بستگی دارد. در برخی بیماران، تنها حرکات بسیار محدود و کنترل‌شده در هفته‌های اول مجاز است و در برخی دیگر، شروع تمرین‌ها به بعد از برداشتن برخی محدودیت‌ها موکول می‌شود. بهترین زمان برای شروع فیزیوتراپی فک را باید جراح فک و صورت شما، بعد از معاینه و بررسی عکس‌ها، مشخص کند.";}}i:1;a:4:{s:5:"@type";s:8:"Question";s:4:"name";s:104:"آیا همه بیماران بعد از جراحی فک به فیزیوتراپی نیاز دارند؟";s:3:"url";s:207:"https://dralirezasadighi.com/%d9%db%8c%d8%b2%db%8c%d9%d8%aa%d8%b1%d8%a7%d9%be%db%8c-%d8%a8%d8%b9%d8%af-%d8%a7%d8%b2-%d8%ac%d8%b1%d8%a7%d8%ad%db%8c-%d9%da%a9-%d8%b1%d8%a7%d9%d9%d9%d8%a7%db%8c-%da%a9%d8%a7%d9/";s:14:"acceptedAnswer";a:2:{s:5:"@type";s:6:"Answer";s:4:"text";s:733:"نیاز به فیزیوتراپی بعد از جراحی فک برای همه بیماران یکسان نیست. در برخی موارد، انجام منظم تمرین‌های ساده‌ای که جراح آموزش می‌دهد کافی است؛ در برخی دیگر، به‌ویژه اگر:
دامنه باز شدن دهان محدود بماند، یا مفصل فک سابقه مشکل داشته باشد، ممکن است جراح شما را برای برنامه فیزیوتراپی تخصصی به فیزیوتراپیست ارجاع دهد. تصمیم نهایی درباره نیاز به فیزیوتراپی، پس از معاینه حضوری و مشاهده روند بهبودی گرفته می‌شود.";}}i:2;a:4:{s:5:"@type";s:8:"Question";s:4:"name";s:135:"تمرین‌های فیزیوتراپی فک را می‌توانم از اینترنت بردارم و خودم انجام بدهم؟";s:3:"url";s:207:"https://dralirezasadighi.com/%d9%db%8c%d8%b2%db%8c%d9%d8%aa%d8%b1%d8%a7%d9%be%db%8c-%d8%a8%d8%b9%d8%af-%d8%a7%d8%b2-%d8%ac%d8%b1%d8%a7%d8%ad%db%8c-%d9%da%a9-%d8%b1%d8%a7%d9%d9%d9%d8%a7%db%8c-%da%a9%d8%a7%d9/";s:14:"acceptedAnswer";a:2:{s:5:"@type";s:6:"Answer";s:4:"text";s:648:"خیر. هرچند ممکن است در اینترنت تمرین‌های مختلفی برای فیزیوتراپی فک ببینید، اما انجام خودسرانه این تمرین‌ها می‌تواند برای برخی بیماران مناسب نباشد. نوع جراحی، وضعیت مفصل، میزان تثبیت فک و شرایط استخوان‌ها در هر فرد متفاوت است.
به همین دلیل، تمرین‌های فیزیوتراپی بعد از جراحی فک باید حتماً توسط جراح و/یا فیزیوتراپیست شما نسخه شود و در صورت نیاز اصلاح شود.";}}i:3;a:4:{s:5:"@type";s:8:"Question";s:4:"name";s:94:"درد هنگام انجام تمرین‌های فیزیوتراپی فک طبیعی است؟";s:3:"url";s:207:"https://dralirezasadighi.com/%d9%db%8c%d8%b2%db%8c%d9%d8%aa%d8%b1%d8%a7%d9%be%db%8c-%d8%a8%d8%b9%d8%af-%d8%a7%d8%b2-%d8%ac%d8%b1%d8%a7%d8%ad%db%8c-%d9%da%a9-%d8%b1%d8%a7%d9%d9%d9%d8%a7%db%8c-%da%a9%d8%a7%d9/";s:14:"acceptedAnswer";a:2:{s:5:"@type";s:6:"Answer";s:4:"text";s:658:"احساس کشش یا کمی ناراحتی خفیف هنگام انجام برخی تمرین‌های فیزیوتراپی فک (در محدوده‌ای که جراح مشخص کرده) می‌تواند تا حدی طبیعی باشد؛ اما درد شدید، تیرکشنده یا درد ماندگار بعد از تمرین، طبیعی نیست و باید جدی گرفته شود. در صورت بروز درد شدید، بهتر است تمرین را متوقف کرده و موضوع را با جراح یا فیزیوتراپیست خود در میان بگذارید تا در صورت نیاز، برنامه تمرین اصلاح شود.";}}}}
